from __future__ import annotations

__doc__ = """
C-oriented ADAAs and coefficient backend definitions.

The C backend stores coefficient arrays as actual ``ctypes`` C arrays and uses
an auxiliary native shared library for the fundamental coefficient operations.
This keeps the ADAA ownership model aligned with the C ABI: ``_data`` already
contains the native storage passed into generated C routines.
"""

import ctypes
from pathlib import Path
from typing import Any

import numpy as np

from ....adaa import ComplexArrayADAA, ImagArrayADAA, RealArrayADAA
from ....coeffbackend import CoeffBackend
from ...backend_config import Configuration


class _CBasicOpsLibrary:
    """Lazy-loaded shared library for fundamental operations on C-backed coeffs."""

    _instance = None

    @classmethod
    def get(cls):
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def __init__(self):
        target = self.resolve_target()
        self._lib = ctypes.CDLL(str(target))

    @staticmethod
    def resolve_target() -> Path:
        """Return the configured support-library path for the C backend."""
        config = Configuration.for_backend("c")
        target = config.get_nested("support", "library_file", default=None)
        if not target:
            raise RuntimeError(
                "missing C backend support library configuration; run "
                "'phoenix-config --dialogue c' first"
            )
        path = Path(target)
        if not path.exists():
            raise RuntimeError(
                f"configured C backend support library does not exist: {path}\n"
                "Run 'phoenix-config --dialogue c' to regenerate it."
            )
        return path

    @property
    def lib(self):
        return self._lib


class CCoeffBackend(CoeffBackend):
    """Coefficient backend storing host data as actual C arrays."""

    CTYPE_LOOKUP = {
        "f32": ctypes.c_float,
        "f64": ctypes.c_double,
        "i32": ctypes.c_int32,
        "i64": ctypes.c_int64,
    }

    NP_DTYPE_LOOKUP = {
        "f32": np.float32,
        "f64": np.float64,
        "i32": np.int32,
        "i64": np.int64,
    }

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._ops = None
        self._is_configured = False

    @property
    def ops(self):
        """Return the configured native helper library."""
        if self._ops is None:
            self._ops = _CBasicOpsLibrary.get().lib
        if not self._is_configured:
            self._configure_ctypes()
            self._is_configured = True
        return self._ops

    def _configure_ctypes(self):
        ops = self._ops
        for dtype, ctype in type(self).CTYPE_LOOKUP.items():
            zero = getattr(ops, f"coeff_zero_{dtype}")
            zero.argtypes = [ctypes.POINTER(ctype), ctypes.c_size_t]
            zero.restype = None

            copy = getattr(ops, f"coeff_copy_{dtype}")
            copy.argtypes = [
                ctypes.POINTER(ctype),
                ctypes.POINTER(ctype),
                ctypes.c_size_t,
            ]
            copy.restype = None

            linop = getattr(ops, f"coeff_linop_{dtype}")
            linop.argtypes = [
                ctypes.POINTER(ctype),
                ctype,
                ctypes.POINTER(ctype),
                ctypes.c_int,
                ctype,
                ctypes.POINTER(ctype),
                ctypes.c_int,
                ctypes.c_int,
                ctypes.c_size_t,
                ctypes.c_int,
            ]
            linop.restype = None

    def coeff_new_array(self, size: int, dtype: str):
        ctype = type(self).CTYPE_LOOKUP[dtype]
        return (ctype * size)()

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str,
    ) -> None:
        array = np.asarray(nparray, dtype=type(self).NP_DTYPE_LOOKUP[dtype])
        if array.ndim != 1:
            raise ValueError("C backend expects 1D arrays.")
        if len(array) != size:
            raise ValueError(
                f"Wrong input size {len(array)} for C dtype {dtype}, expected {size}."
            )
        for num, val in enumerate(array):
            coeff_like[num] = val.item() if hasattr(val, "item") else val

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str
    ) -> np.ndarray:
        out = np.ctypeslib.as_array(coeff_like, shape=(size,))
        return np.array(out, dtype=type(self).NP_DTYPE_LOOKUP[dtype], copy=True)

    def coeff_to_zero(self, coeff_like: Any, size: int, dtype: str):
        zero = getattr(self.ops, f"coeff_zero_{dtype}")
        zero(coeff_like, size)

    def coeff_copy_data(self, targ: Any, source: Any, size: int, dtype: str):
        copy = getattr(self.ops, f"coeff_copy_{dtype}")
        copy(targ, source, size)

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any,
        *,
        size: int,
        dtype: str,
        inplace: bool = False,
    ):
        ctype = type(self).CTYPE_LOOKUP[dtype]
        linop = getattr(self.ops, f"coeff_linop_{dtype}")
        null = ctypes.POINTER(ctype)()

        if arr_x is None:
            arr_x = null
        if arr_y is None:
            arr_y = null

        a_value = ctype(1 if scal_a is None else scal_a)
        use_y = int(arr_y is not null)
        if not use_y:
            scal_b = None
        b_value = ctype(0 if scal_b is None else scal_b)

        linop(
            arr_r,
            a_value,
            arr_x,
            int(scal_a is not None),
            b_value,
            arr_y,
            int(scal_b is not None),
            use_y,
            size,
            int(inplace),
        )


class CCA(
    ComplexArrayADAA,
    backend=CCoeffBackend(),
    identifier="C",
    is_anchor=True,
):
    """Complex ADAA storing data in C-native host arrays."""


class CRA(
    RealArrayADAA,
    backend=CCoeffBackend(),
    identifier="C",
    is_anchor=True,
):
    """Real ADAA storing data in C-native host arrays."""


class CIA(
    ImagArrayADAA,
    backend=CCoeffBackend(),
    identifier="C",
    is_anchor=True,
):
    """Purely imaginary ADAA storing data in C-native host arrays."""


__all__ = [
    "CCoeffBackend",
    "CCA",
    "CRA",
    "CIA",
]
